/*
Dot Number Fractal - Svenofnine
https://www.shadertoy.com/view/MXVcDG
*/

#define R iResolution

// Maybe I should use an array and trust the compiler 
const 
uint[] pattern = uint[10] (
  15255086u, // "0" =(14u<<20) + (17u<<15) + (17u<<10) + (17u<<5) + 14u;
  12718222u, // "1" =(12u<<20) +  (4u<<15) +  (4u<<10) +  (4u<<5) + 14u;
  31504927u, // "2" =(30u<<20) +  (1u<<15) + (14u<<10) + (16u<<5) + 31u;
  31504446u, // "3" =(30u<<20) +  (1u<<15) + (14u<<10) +  (1u<<5) + 30u;
  19496002u, // "4" =(18u<<20) + (18u<<15) + (31u<<10) +  (2u<<5) +  2u;
  33060926u, // "5" =(31u<<20) + (16u<<15) + (30u<<10) +  (1u<<5) + 30u;
  15235630u, // "6" =(14u<<20) + (16u<<15) + (30u<<10) + (17u<<5) + 14u;
  32540808u, // "7" =(31u<<20) +  (1u<<15) +  (2u<<10) +  (4u<<5) +  8u;
  15252014u, // "8" =(14u<<20) + (17u<<15) + (14u<<10) + (17u<<5) + 14u;
  15252526u  // "9" =(14u<<20) + (17u<<15) + (15u<<10) +  (1u<<5) + 14u;
);


float write_digit(vec2 uv, vec2 pos, int digit_id, bool just_one ) {  
    vec2 d = fract(uv-pos-.505); //(iMouse.x/R.x));
    uint bits = pattern[digit_id];     // use the const-[]
    float o = .0;
    // between which four dot matrix pixels of the character does uv go through?
    uint ax = uint(5.-d.x*6.25);                     
    uint ay = uint(d.y*6.25 - 1.);
    if(ay<5u)
        for(uint y=ay; y<=ay+1u; y++)
            for(uint x=ax; x<=min(ax+1u,4u); x++)
              if( ( bits & ( 1u<<(y*5u+x) ) ) > 0u)
                  o += smoothstep( .14, .0, distance( d, .16 * vec2( uvec2(5u-x, 1u+y) ) ) );    
    return o;
}

void mainImage( out vec4 C, in vec2 S )
{
    vec2 uv = (S - .5*R.xy) / R.y;

    float m, brightness;

    float T = iTime;

    //T = 2.0;

    m = 0.8-fract(T);//fract(2.*iMouse.x/R.x);

    int digit = int(mod(T, 10.));
    int prev_digit = (digit+9)%10;
    int next_digit = (digit+1)%10;

    vec2[] moves = vec2[10] (
        vec2(0.,0.), vec2(0.,.5),vec2(2.,0.), vec2(0.,0.),vec2(0.,0.), 
        vec2(0.,0.),vec2(0.,0.), vec2(-1.,0.),vec2(1.,0.), vec2(1.5,0.)
    );

    uv += mix( moves[digit], moves[next_digit], fract(T));

    brightness = write_digit(uv*pow(6.,m-1.), vec2(.0), prev_digit, true );
    brightness *= write_digit(uv*pow(6.,m),vec2(.0), digit, false);
    brightness *= mix(1., write_digit(uv*pow(6.,m+1.),  vec2(.0),next_digit,false),fract(T));

   C = vec4(vec3(brightness),1.0);
}
